  // ── Start ────────────────────────────────────────────────────────────────
  "guide.start.what.h": "What this is",
  "guide.start.what.b": "Vạn Thắng is a strategy game about Đại Việt, printed like a Đông Hồ woodblock. The realm keeps its own clock: fields are cleared, men are raised, hosts march — none of it waits for you. What you do is decide. The game stops and asks.",
  "guide.start.modes.h": "Three ways to play",
  "guide.start.modes.b": "Dragon Ascent is the big button on the front page and the one to start with. The other two are behind Classic Modes, and are played by hand.",
